// Пакет «граф + офлайн-данные»: node tools/test-bundle.mjs
import vm from 'node:vm'; import fs from 'node:fs';
const ctx=vm.createContext({Math,isFinite,Number,Object,Array,String,Boolean,BigInt,Date,Map,Set,Blob,ArrayBuffer,Uint8Array,Int8Array,Uint8ClampedArray,Int16Array,Uint16Array,Int32Array,Uint32Array,Float32Array,Float64Array,btoa,atob,JSON,Error});
const rd=f=>fs.readFileSync(new URL('../modules/'+f,import.meta.url),'utf8');
vm.runInContext(rd('backup-kernels.js')+rd('bundle-kernels.js')+';this.K={bundlePack,bundleUnpack,bundleMB,BUNDLE_FORMAT};',ctx);
const K=ctx.K; let bad=0; const ok=(n,c,i='')=>{ if(!c){ bad++; console.log('FAIL',n,i); } else console.log('ok  ',n); };
const g={nodes:[{id:1,type:'clock'}],edges:[]}, data=new Uint8Array(300000).map((_,i)=>i*7&255);
const blob=await K.bundlePack(g,[{name:'model.bin',blob:new Blob([data])},{name:'dict.json',blob:new Blob(['{"a":1}'],{type:'application/json'})}]);
const o=JSON.parse(await blob.text());
ok('формат',o.format===K.BUNDLE_FORMAT&&o.v===1&&o.offline.length===2);
const u=K.bundleUnpack(o);
ok('граф вернулся',JSON.stringify(u.graph)===JSON.stringify(g));
const b0=new Uint8Array(await u.files[0].blob.arrayBuffer());
ok('файл побайтно',u.files[0].name==='model.bin'&&b0.length===data.length&&b0.every((x,i)=>x===data[i]));
ok('тип сохранён',u.files[1].blob.type==='application/json'&&await u.files[1].blob.text()==='{"a":1}');
ok('без файлов',K.bundleUnpack(JSON.parse(await (await K.bundlePack(g,[])).text())).files.length===0);
const t=(f)=>{ try{ f(); return false; }catch(e){ return true; } };
ok('чужой файл — ошибка',t(()=>K.bundleUnpack({nodes:[]}))&&t(()=>K.bundleUnpack(null))&&t(()=>K.bundleUnpack({format:K.BUNDLE_FORMAT})));
const bad2=K.bundleUnpack({format:K.BUNDLE_FORMAT,graph:g,offline:[{name:'../x',data:{$:'blob',type:'',b:'AA=='}},{name:'',data:null},null,{name:'ok.bin',data:{$:'blob',type:'',b:'AQID'}},{name:'empty',data:{$:'blob',type:'',b:''}}]});
ok('пути, пустое и мусор отбрасываются',bad2.files.length===1&&bad2.files[0].name==='ok.bin');
ok('размер',K.bundleMB(1572864)==='1.5 MB'&&K.bundleMB(50*1048576)==='50 MB');
process.exit(bad?1:0);
